PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('CUSTOMER','STAFF','ORGANIZER','MANAGER')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id), full_name TEXT NOT NULL DEFAULT '', email TEXT UNIQUE, phone TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gaming_stations (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, type TEXT NOT NULL, specs TEXT NOT NULL DEFAULT '', hourly_rate_paisa INTEGER NOT NULL CHECK(hourly_rate_paisa>0), status TEXT NOT NULL DEFAULT 'AVAILABLE', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reservations (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, station_id INTEGER NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(station_id) REFERENCES gaming_stations(id), CHECK(starts_at<ends_at));
CREATE INDEX IF NOT EXISTS idx_reservations_overlap ON reservations(station_id,starts_at,ends_at,status);
CREATE TABLE IF NOT EXISTS charges (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), source_type TEXT NOT NULL, source_id INTEGER NOT NULL, amount_paisa INTEGER NOT NULL CHECK(amount_paisa>=0), status TEXT NOT NULL DEFAULT 'UNPAID', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,plan TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,status TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS teams (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,captain_id INTEGER NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(captain_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS team_members (team_id INTEGER NOT NULL,user_id INTEGER NOT NULL,status TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'MEMBER',joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(team_id,user_id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tournaments (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,format TEXT NOT NULL,fee_paisa INTEGER NOT NULL,status TEXT NOT NULL,created_by INTEGER NOT NULL,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS registrations (id INTEGER PRIMARY KEY AUTOINCREMENT,tournament_id INTEGER NOT NULL,user_id INTEGER,team_id INTEGER,fee_paisa INTEGER NOT NULL,fee_status TEXT NOT NULL DEFAULT 'PAID',status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(team_id) REFERENCES teams(id),CHECK((user_id IS NOT NULL AND team_id IS NULL) OR (user_id IS NULL AND team_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,reservation_id INTEGER, user_id INTEGER NOT NULL REFERENCES users(id),station_id INTEGER NOT NULL REFERENCES gaming_stations(id),started_at TEXT NOT NULL,planned_end_at TEXT,ended_at TEXT,status TEXT NOT NULL,charge_paisa INTEGER NOT NULL DEFAULT 0,charge_id INTEGER REFERENCES charges(id),FOREIGN KEY(reservation_id) REFERENCES reservations(id));
CREATE INDEX IF NOT EXISTS idx_sessions_station ON sessions(station_id,status);
CREATE TABLE IF NOT EXISTS maintenance (id INTEGER PRIMARY KEY AUTOINCREMENT,station_id INTEGER NOT NULL REFERENCES gaming_stations(id),description TEXT NOT NULL,severity TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'REPORTED',created_at TEXT NOT NULL,resolved_at TEXT,resolution_notes TEXT,reported_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,charge_id INTEGER REFERENCES charges(id),amount_paisa INTEGER NOT NULL CHECK(amount_paisa>0),method TEXT NOT NULL,reference TEXT,status TEXT NOT NULL,idempotency_key TEXT UNIQUE,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_payments_charge ON payments(charge_id);
CREATE TABLE IF NOT EXISTS receipts (id INTEGER PRIMARY KEY AUTOINCREMENT,payment_id INTEGER NOT NULL UNIQUE REFERENCES payments(id),receipt_number TEXT NOT NULL UNIQUE,issued_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS membership_plans (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,price_paisa INTEGER NOT NULL,duration_days INTEGER NOT NULL,discount_percent INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS team_join_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,team_id INTEGER NOT NULL REFERENCES teams(id),user_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'PENDING',decided_by INTEGER REFERENCES users(id),decided_at TEXT);
CREATE TABLE IF NOT EXISTS tournament_matches (id INTEGER PRIMARY KEY AUTOINCREMENT,tournament_id INTEGER NOT NULL REFERENCES tournaments(id),round_no INTEGER NOT NULL,slot_no INTEGER NOT NULL,player_a INTEGER REFERENCES registrations(id),player_b INTEGER REFERENCES registrations(id),station_id INTEGER REFERENCES gaming_stations(id),scheduled_at TEXT,status TEXT NOT NULL DEFAULT 'SCHEDULED',winner_registration_id INTEGER REFERENCES registrations(id),UNIQUE(tournament_id,round_no,slot_no));
CREATE TABLE IF NOT EXISTS match_results (id INTEGER PRIMARY KEY AUTOINCREMENT,match_id INTEGER NOT NULL UNIQUE REFERENCES tournament_matches(id),score_a INTEGER NOT NULL,score_b INTEGER NOT NULL,winner_registration_id INTEGER NOT NULL REFERENCES registrations(id),confirmed_by INTEGER NOT NULL REFERENCES users(id),confirmed_at TEXT NOT NULL,revision_no INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT,actor_user_id INTEGER REFERENCES users(id),entity_type TEXT NOT NULL,entity_id INTEGER,operation TEXT NOT NULL,before_summary TEXT,after_summary TEXT,reason TEXT,created_at TEXT NOT NULL);
